// A small framework in the shape of velox: it calls Bun.serve itself, hands each handler a
// `ctx` whose `params` is validated lazily (a getter that throws on bad input), and answers a
// handler's error with a 500. tests/parity serves the same app on it from TypeScript under Bun
// and from Tov.

class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValidationError";
  }
}

// `/users/:name` -> a matcher returning the raw params, or null
function compile(path) {
  const names = [];
  const re = new RegExp("^" + path.replace(/:([a-z]+)/g, (_, n) => (names.push(n), "([^/]+)")) + "$");
  return (pathname) => {
    const m = re.exec(pathname);
    if (!m) return null;
    const out = {};
    names.forEach((n, i) => (out[n] = decodeURIComponent(m[i + 1])));
    return out;
  };
}

function makeCtx(raw, url) {
  let params;
  return {
    query: Object.fromEntries(url.searchParams),
    get params() {
      if (params) return params;
      for (const [k, v] of Object.entries(raw)) {
        if (v.length < 2) throw new ValidationError(`${k}: too short (min: 2)`);
      }
      return (params = raw);
    },
    fail(message) {
      throw new Error(message);
    },
  };
}

function answer(value) {
  if (value instanceof Response) return value;
  if (typeof value === "string") return new Response(value);
  return Response.json(value ?? null);
}

function failure(e) {
  const name = e instanceof Error ? e.name : "Error";
  const message = e instanceof Error ? e.message : String(e);
  return Response.json({ error: name, message }, { status: 500 });
}

// createApp().route(path, handler)...listen(port)
export function createApp() {
  const table = [];
  return {
    route(path, handler) {
      table.push([compile(path), handler]);
      return this;
    },
    listen(port) {
      return Bun.serve({
        port,
        async fetch(req) {
          const url = new URL(req.url);
          for (const [match, handler] of table) {
            const raw = match(url.pathname);
            if (!raw) continue;
            try {
              return answer(await handler(makeCtx(raw, url)));
            } catch (e) {
              return failure(e);
            }
          }
          return new Response("Not Found", { status: 404 });
        },
      });
    },
  };
}
